"""English field labels and operational help; source metadata remains verbatim."""
FIELDS_EN={
 'record_id':('Internal identifier','Generated automatically; remains stable when the experiment is reopened.'),
 'kind':('Reading type','Select reagent blank, calibration standard, quality control or sample. Custom names must map to one of these calculation categories.'),
 'sample_id':('Sample / standard','Required name used in results and figures. Use the same name for replicates of one sample or calibration level; different varieties need different names.'),
 'bio_id':('Experimental unit\n/ extraction','Required identifier of an independently prepared specimen, extraction or run; it need not be a living organism. Repeated readings of the same preparation share this unit and use different reading IDs. Use Batch 1 for standards/blanks if appropriate. The application cannot certify independence.'),
 'tech_id':('Reading\nreplicate','Required identifier of a technical reading, unique within its unit. This does not increase the independent sample size.'),
 'concentration':('Standard\nconcentration','Required for standards and controls, not samples or blanks. Enter a finite value ≥0 in the concentration units and before/final reaction basis specified by this protocol.'),
 'A_end':('Final absorbance\nAU','Original final absorbance reading. Required finite number, e.g. 0.430. Both decimal point and comma are accepted. Negative readings are retained for review.'),
 'A_initial':('Initial absorbance\nAU','Original reading before reaction; required for change/delta protocols. Response is final minus initial. Not used for endpoint protocols.'),
 'matrix_blank_delta':('Net matrix correction\nAU','Required finite additional matrix correction, already corrected for its own blank/initial reading. Enter 0 explicitly if not applicable. Do not subtract the reagent blank a second time.'),
 'dilution':('Previous dilution\nfactor · ×','Positive factor for samples. 1 = undiluted; 2 = one part extract made up to two parts total volume. Multiply successive dilution factors. Excludes dilution on adding the assay reagent.'),
 'extract_mL':('Total extract\nvolume · mL','Positive total extraction volume in millilitres, not the aliquot added to the assay. Must correspond to the reference mass entered for this sample.'),
 'mass_g':('Reference mass\ng','Positive reference mass in grams. Record whether fresh biomass, dry material or dry extract; the application does not convert between mass bases.'),
 'expected':('Expected control\nconcentration','Positive expected concentration for quality controls, in calibration-axis units. Enter concentration, not recovery percentage.'),
 'notes':('Notes','Optional observations retained with the original data.'),
 'kind_label':('Custom reading type','Optional custom name mapped to an analytical category; stored with the row.'),
 'tare_g':('Container tare · g','Empty container mass m0, in grams; required and ≥0. Do not enter net sample mass.'),
 'initial_g':('Container + initial\nsample · g','Initial total mass m1, in grams. Must exceed tare; initial net sample mass is m1−m0.'),
 'final_g':('Container + final\nresidue · g','Final total mass m2 after drying or ashing. Require m0≤m2≤m1. Record actual endpoint conditions.'),
 'dry_fraction':('Dry fraction · 0–1','For ash expressed on a dry basis when the initial sample is not already dry. Enter 0.9 for 90% dry matter, not 90; do not correct twice.'),
 'lower_um':('Lower retained\nbound · µm','Lower size bound, e.g. 100 for a 100–300 µm fraction. Collector pan: 0. Required and ≥0.'),
 'upper_um':('Upper passing\nbound · µm','Upper size bound, greater than lower bound. Leave empty only for the open upper fraction. Enter actual apertures, not mesh numbers.'),
 'retained_g':('Fraction retained\nmass · g','Net mass of this fraction, including collector pan. One row per fraction and independent sieving unit.'),
 'loaded_g':('Total loaded\nmass · g','Initial total mass loaded for this sieving unit. Repeat across its fractions. Percentages use this mass without renormalising recovery to 100%.'),
 'dose_mg_mL':('Extract dose\nmg/mL FINAL','DPPH EC50: dry extract concentration in the final reaction mixture, not in the aliquot. For 0.1+3.9 mL, divide aliquot concentration by 40. Each unit needs a dose series.'),
 'time_min':('Reading time\nmin','Actual elapsed time after mixing, in minutes. DPPH needs a radical control at the same time. All kinetic readings are retained.'),
 'plateau':('Plateau confirmed','Mark Yes exactly once, at the final reading of each dose/technical-replicate series after checking stability. Plateau detection is not automatic.'),
}
PARAMETERS_EN={
 'method':('Method','Analytical family. Each assay retains its own protocol, data and calculation.'),
 'name':('Protocol name','Recognisable variant name. Saving a variant creates a separate version.'),
 'id':('Protocol identifier','Internal protocol identifier; not edited manually.'),
 'version':('Protocol version','Version retained with the experiment.'),
 'status':('Protocol status','Documented transfer/validation status. Software checks do not validate the chemistry.'),
 'response':('Analytical response','Choose change from initial reading or endpoint according to the method. DPPH uses inhibition at each time.'),
 'equivalent':('Calibration reference','Chemical reference used in calibration and result units. Changing the reference requires the corresponding calibration.'),
 'concentration_unit':('Concentration unit','Unit of standards in this variant. Keep standards, curve and result units consistent.'),
 'calibration_basis':('Calibration concentration basis','Before reaction: concentration in the pipetted vial. Final mixture: concentration after mixing; reaction dilution is applied once.'),
 'wavelength_nm':('Wavelength · nm','Actual absorbance wavelength in nanometres; must match the chosen method.'),
 'temperature_C':('Temperature · °C','Actual temperature. Leave unspecified where the documented method does not prescribe a numeric value; record your conditions.'),
 'time_min':('Reaction / reading time · min','Protocol time. DPPH uses actual times entered per row and operator-confirmed plateaus. Constant-mass drying may use a documented endpoint criterion instead of a fixed time.'),
 'aliquot_uL':('Sample / standard aliquot · µL','Positive volume pipetted into the reaction, in microlitres. Not total extraction volume.'),
 'reagent_uL':('Reagents and solvents · µL','Total volume added apart from aliquot and additional water. Document the component recipe under Reagent preparation.'),
 'water_uL':('Additional water · µL','Water added to the reaction, ≥0. Aliquot + reagents + water gives the final reaction volume.'),
 'report_factor':('Result expression factor','Variant-specific conversion factor. Select a consistent variant rather than changing units alone.'),
 'result_unit':('Result unit','Unit and chemical equivalent of the result, consistent with the calibration reference.'),
 'mass_basis':('Mass basis','Specify dry leaf, dry extract, fresh biomass, etc. No automatic conversion between mass bases.'),
 'r2_min':('Minimum R² · provisional','Editable provisional QC threshold, between 0 and 1. High R² alone does not establish validity.'),
 'cv_max_percent':('Maximum technical CV · %','Positive provisional coefficient-of-variation limit for technical readings of the same unit.'),
 'recovery_min_percent':('Minimum recovery · %','Provisional lower control recovery limit; must be below the upper limit.'),
 'recovery_max_percent':('Maximum recovery · %','Provisional upper control recovery limit; not analytical validation.'),
 'qc_policy':('QC interpretation','Provisional status and interpretation of quality-control criteria.'),
 'reagents':('Reagent preparation','Concentrations, composition and recipe provenance. Editable and traceable; does not replace the experimental protocol.'),
 'notes':('Protocol notes','Specific conditions, darkness, solvent and observations.'),
 'source':('Protocol source','Optional reference or link to the consulted method. You may leave it empty. If provided, it is retained with each experiment.'),
 'source_updated':('Source update date','Documented source update date; not a validation date.'),
 'source_retrieved':('Source retrieval date','Date the source was consulted to prepare the catalogue; not source publication or analytical validation.'),
 'standard_range':('Documented calibration range','Range in the source. Actual interpolation range follows entered calibration standards; concentrations are not generated automatically.'),
 'engine':('Calculation engine','Mathematical engine associated with this method; do not substitute another assay manually.'),
 'reaction_total_uL':('Documented final volume · µL','When specified, must equal aliquot + reagents + water. CUPRAC: 4100 µL; enter actual aliquot and water.'),
 'quantity':('Gravimetric quantity','Moisture, dry matter or ash; these use different equations.'),
 'ash_basis':('Ash expression basis','Initial basis: residue/net initial mass. Dry basis also divides by the corresponding dry fraction. Avoid double correction.'),
 'endpoint_note':('Endpoint / constant-mass criterion','Document cycles, endpoint criterion and actual conditions. No undocumented tolerance is invented.'),
 'blocked_reason':('Missing method information','Why this documentary adaptation cannot yet be treated as a complete procedure.'),
 'operational_confirmed':('Operating conditions completed','For incomplete TAPPI adaptations: confirm only after identifying the standard and recording conditions. Does not constitute analytical validation.'),
 'standard_reference':('Confirmed operating reference','Identify standard code and edition or the reference completing this adaptation.'),
 'sieve_amplitude':('Sieving amplitude and conditions','Record amplitude, equipment, load and preparation. Missing source values are not invented.'),
 'mass_recovery_min':('Minimum mass recovery · %','Editable provisional sieving balance limit; fractions are not renormalised.'),
 'mass_recovery_max':('Maximum mass recovery · %','Editable provisional balance limit; review losses, duplicate fractions and masses.'),
}

def register():
    from .i18n import add
    for es,en in {
        'Editar las condiciones del protocolo de este ensayo':'Edit this assay’s protocol conditions',
        'Referencia bibliográfica':'Source reference',
        'Abrir artículo original / fuente':'Open original article / source',
        'Introduce un enlace web para la fuente.':'Enter a web link for the source.',
        'Custom protocol':'Custom protocol',
        'Empieza añadiendo un ensayo':'Start by adding an assay',
        'Elige el método y su protocolo para empezar a introducir datos.':'Choose a method and protocol to start entering data.',
        'Nuevo ensayo':'New assay',
        'Añade un ensayo antes de guardar.':'Add an assay before saving.',
        'Excel está abierto o se está abriendo. Guarda y cierra el libro del experimento antes de actualizar y exportar.':'Excel is open or opening. Save and close the experiment workbook before updating and exporting.',
    }.items():add(es,en)
    from .ui_fields import FIELDS,PARAMETERS
    from .i18n import add
    for source,target in ((FIELDS,FIELDS_EN),(PARAMETERS,PARAMETERS_EN)):
        for key,(label,helptext) in target.items():
            if key in source:
                add(source[key][0],label);add(source[key][1],helptext)
